def test_type_alias_parsing():
    """
    Type aliases should resolve to the same walk as their source
    """
    file = Path(__file__).parent / 'tmc_files' / 'tc_mot_example.tmc'
    tmc_item = parse(file)
    dut_mot = None
    st_mot = None
    for dtyp in tmc_item.DataTypes[0].DataType:
        if dtyp.name == 'DUT_MotionStage':
            dut_mot = dtyp
        elif dtyp.name == 'ST_MotionStage':
            st_mot = dtyp
    assert dut_mot is not None, "Did not find DUT_MotionStage in test setup"
    assert st_mot is not None, "Did not find ST_MotionStage in test setup"
    assert list(dut_mot.walk()) == list(st_mot.walk())


def _parse_pragma(text):
    """
    Parse a raw pragma string and return (pvname, normalised config dict)
    for the first pv found.
    """
    lines = split_pytmc_pragma(text)
    for pvname, cfg_lines in separate_configs_by_pv(lines):
        return pvname, normalize_config(dictify_config(cfg_lines))
    return None, None


def test_pragma_alias_before_pv_is_not_dropped():
    """
    alias: declared before pv: must survive pragma parsing and appear in
    the normalised config dict.
    """
    _, config = _parse_pragma("""
        alias: TST:SLITZ.LLS
        pv: TST:SLITZ:btestLLS
        io: i
    """)
    assert config.get("alias") == "TST:SLITZ.LLS"


def test_pragma_alias_after_pv_still_works():
    """alias: declared after pv: must continue to work as before."""
    _, config = _parse_pragma("""
        pv: TST:SLITZ:btestLLS
        alias: TST:SLITZ.LLS
        io: i
    """)
    assert config.get("alias") == "TST:SLITZ.LLS"


def test_pragma_io_before_pv_is_not_dropped():
    """io: declared before pv: must survive pragma parsing."""
    _, config = _parse_pragma("""
        io: i
        pv: TST:M1:fActPosition
    """)
    assert config.get("io") == "input"


def test_pragma_multiple_keys_before_pv_all_preserved():
    """Multiple pragma keys declared before pv: must all be preserved."""
    _, config = _parse_pragma("""
        alias: TST:M1.RBV
        io: i
        pv: TST:M1:fActPosition
        field: DESC Actual position
    """)
    assert config.get("alias") == "TST:M1.RBV"
    assert config.get("io") == "input"


def test_pragma_pvname_correct_with_pre_pv_lines():
    """The pv name must be correctly extracted when preceding lines are buffered."""
    pvname, _ = _parse_pragma("""
        alias: TST:SLITZ.LLS
        pv: TST:SLITZ:btestLLS
        io: i
    """)
    assert pvname == "TST:SLITZ:btestLLS"


def test_pragma_no_pre_pv_lines_no_regression():
    """A pragma with no pre-pv lines must behave identically to before."""
    pvname, config = _parse_pragma("""
        pv: TST:M1:fPos
        io: io
        field: DESC Desired position
    """)
    assert pvname == "TST:M1:fPos"
    assert config.get("io") == "output"


def test_pragma_pre_pv_lines_do_not_bleed_into_second_pv_block():
    """
    Pre-pv buffered lines must only attach to the immediately following
    pv block and must not bleed into subsequent pv blocks.
    """
    lines = split_pytmc_pragma("""
        alias: TST:M1.RBV
        pv: TST:M1:fActPosition
        io: i
        pv: TST:M1:fVelocity
        io: i
    """)
    results = list(separate_configs_by_pv(lines))
    assert len(results) == 2

    d1 = dictify_config(results[0][1])
    d2 = dictify_config(results[1][1])

    assert d1.get("alias") == "TST:M1.RBV"
    assert d2.get("alias") is None, (
        "alias from the first pv block must not bleed into the second"
    )


def _array_proxies_for(pragma_text, *, low=1, high=4):
    """Run handle_array_complex and return the per-element proxies.

    Builds an array of complex (string) data type, runs it through
    chains_from_symbol so handle_array_complex installs any per-element
    overrides, and returns the resulting _ArrayItemProxy objects in
    declaration order.
    """
    array = _make_mock_twincatitem(
        name="Main.motors",
        data_type=_make_mock_type("MY_STRING", is_string=True),
        pragma=pragma_text,
        array_info=(low, high),
    )
    return [chain.last for chain in _pragmas.chains_from_symbol(array)]


def test_get_axis_link_returns_override_when_present():
    """A proxy with axis_link_override returns the substituted value."""
    proxies = _array_proxies_for(
        "pv: STATE\nexpand-names: MMS, CLZ, CLF, YAG\n"
        "axis-link: GVL_Axes.Axes[%d]"
    )
    results = [_get_axis_link(p) for p in proxies]
    assert results == [
        "GVL_Axes.Axes[1]",
        "GVL_Axes.Axes[2]",
        "GVL_Axes.Axes[3]",
        "GVL_Axes.Axes[4]",
    ]


def test_get_axis_link_override_with_width_specifier():
    """A '%.2d' template produces zero-padded indices in the override."""
    proxies = _array_proxies_for(
        "pv: STATE\naxis-link: GVL_Axes.Axes[%.2d]",
        low=1,
        high=3,
    )
    results = [_get_axis_link(p) for p in proxies]
    assert results == [
        "GVL_Axes.Axes[01]",
        "GVL_Axes.Axes[02]",
        "GVL_Axes.Axes[03]",
    ]


def test_get_axis_link_override_with_non_unit_lower_bound():
    """Substitution uses the absolute array index, matching GVL layout."""
    proxies = _array_proxies_for(
        "pv: STATE\naxis-link: GVL_Axes.Axes[%d]",
        low=5,
        high=7,
    )
    results = [_get_axis_link(p) for p in proxies]
    assert results == [
        "GVL_Axes.Axes[5]",
        "GVL_Axes.Axes[6]",
        "GVL_Axes.Axes[7]",
    ]


def test_get_axis_link_override_with_explicit_list():
    """Explicit-list form: each proxy returns its own entry from the list.

    This is the form required when the GVL_Axes.Axes pool is shared
    across multiple devices and a given device's afbMotorsNC[1..N]
    references a non-1-based slice (e.g. Axes[5..8] for the second
    device in the project). The implicit %d form would silently wire
    every motor to the wrong axis here; the explicit list is the
    only correct form for this layout.
    """
    proxies = _array_proxies_for(
        "pv: TST:MAL\n"
        "expand-names: MMS, CLZ, CLF, YAG\n"
        "axis-link: GVL_Axes.Axes[5], GVL_Axes.Axes[6], "
        "GVL_Axes.Axes[7], GVL_Axes.Axes[8]"
    )
    results = [_get_axis_link(p) for p in proxies]
    assert results == [
        "GVL_Axes.Axes[5]",
        "GVL_Axes.Axes[6]",
        "GVL_Axes.Axes[7]",
        "GVL_Axes.Axes[8]",
    ]


def test_get_axis_link_explicit_list_with_non_unit_lower_bound():
    """Explicit list is keyed by absolute array position, not list index."""
    proxies = _array_proxies_for(
        "pv: STATE\naxis-link: GVL.A[10], GVL.A[20], GVL.A[30]",
        low=5,
        high=7,
    )
    results = [_get_axis_link(p) for p in proxies]
    # Outer index 5 → first entry, 6 → second, 7 → third
    assert results == ["GVL.A[10]", "GVL.A[20]", "GVL.A[30]"]


def test_get_axis_link_explicit_list_with_array_subset():
    """`array:` slice forces axis-link length to match the selection.

    When `array:` is set, `axis-link` and `expand-names` are validated
    against the slice count, not the full bounds, and entries are
    consumed positionally within the selection.
    """
    proxies = _array_proxies_for(
        "pv: STATE\n"
        "expand-names: MMS, YAG\n"
        "axis-link: GVL.A[5], GVL.A[7]\n"
        "array: 1,3"
    )
    results = [_get_axis_link(p) for p in proxies]
    # Two selected indices (1, 3) consume the two entries in order.
    assert results == ["GVL.A[5]", "GVL.A[7]"]


def test_get_axis_link_explicit_list_slice_count_mismatch_raises():
    """Slice count and axis-link entry count must match exactly."""
    with pytest.raises(ValueError, match="the array: slice"):
        _array_proxies_for(
            "pv: STATE\n"
            "expand-names: MMS, CLZ, CLF, YAG\n"
            "axis-link: GVL.A[5], GVL.A[6], GVL.A[7], GVL.A[8]\n"
            "array: 1,3"
        )


def test_get_axis_link_falls_back_to_pragma_without_override():
    """A symbol without an override returns the literal pragma value."""
    scalar = _make_mock_twincatitem(
        name="Main.motor",
        data_type=_make_mock_type("DINT"),
        pragma="pv: M1\naxis-link: GVL_Axes.Axes[2]",
    )
    assert _get_axis_link(scalar) == "GVL_Axes.Axes[2]"


def test_get_axis_link_no_pragma_returns_none():
    """A symbol with no pytmc pragma at all is treated as ignored."""
    scalar = _make_mock_twincatitem(
        name="Main.motor",
        data_type=_make_mock_type("DINT"),
        pragma=None,
    )
    assert _get_axis_link(scalar) is None


def test_get_axis_link_pragma_without_axis_link_raises():
    """A pytmc pragma present but missing axis-link is a config error."""
    scalar = _make_mock_twincatitem(
        name="Main.motor",
        data_type=_make_mock_type("DINT"),
        pragma="pv: M1\nio: io",
    )
    with pytest.raises(RuntimeError, match="No valid axis-link pragma"):
        _get_axis_link(scalar)
